def open_gpu_page():
    # CEF's HTTP endpoint creates the tab pre-pointed at chrome://gpu, which
    # avoids the cross-origin restrictions that bite Page.navigate from a
    # regular https:// tab into a chrome:// scheme.
    return http("/json/new?chrome://gpu", method="PUT")


def close_page(target_id):
    try:
        urllib.request.urlopen(
            f"{DEVTOOLS}/json/close/{target_id}", timeout=3
        ).read()
    except Exception:
        pass


def dump_gpu(page):
    ws = WS(page["webSocketDebuggerUrl"])
    ws.send_json("Page.enable")
    # chrome://gpu populates asynchronously after navigation; poll until both
    # the feature table and the driver section are rendered, or 15s pass.
    # textContent works regardless of layout (background tabs have no layout
    # computed; innerText would return ""). chrome://gpu renders feature rows
    # as table cells "Name" / "Status", so we walk the DOM and join cell pairs
    # with ": " to get a stable parsable form. Fall back to textContent for
    # the version section.
    expr = r"""
(() => {
  const out = [];
  out.push("=== body.textContent ===");
  out.push(document.body ? document.body.textContent : "");
  out.push("=== feature-status ===");
  for (const row of document.querySelectorAll("#feature-status-list li, .feature-status-list li")) {
    out.push(row.textContent.replace(/\s+/g, " ").trim());
  }
  return out.join("\n");
})()
"""
    deadline = time.monotonic() + 20
    text = ""
    while time.monotonic() < deadline:
        eid = ws.send_json("Runtime.evaluate", {
            "expression": expr,
            "returnByValue": True,
        })
        res = ws.wait_for(eid)
        text = res["result"]["result"].get("value", "") or ""
        if "Graphics Feature Status" in text and "Driver Information" in text:
            break
        time.sleep(0.3)
    return text


def assert_feature_status(text):
    failures = []
    successes = []
    for feat in REQUIRED_HW:
        m = re.search(rf"^\s*\*?\s*{re.escape(feat)}:\s*(.+)$",
                      text, re.MULTILINE)
        if not m:
            failures.append(f"{feat}: not present in chrome://gpu output")
            continue
        status = m.group(1).strip()
        if status.lower().startswith("hardware accelerated"):
            successes.append(f"{feat}: {status}")
        else:
            failures.append(f"{feat}: expected 'Hardware accelerated', got '{status}'")
    name, pat = REQUIRED_RASTER
    m = re.search(rf"^\s*\*?\s*{re.escape(name)}:\s*(.+)$",
                  text, re.MULTILINE)
    if not m:
        failures.append(f"{name}: not present")
    elif not pat.search(m.group(1)):
        failures.append(f"{name}: expected hardware accelerated, got '{m.group(1).strip()}'")
    else:
        successes.append(f"{name}: {m.group(1).strip()}")

    impl = re.search(r"GL implementation parts\s*:\s*(.+)$",
                     text, re.MULTILINE)
    if not impl or not REQUIRED_ANGLE.search(impl.group(1)):
        failures.append("GL implementation: ANGLE/Metal not active "
                        f"(saw '{impl.group(1).strip() if impl else 'absent'}')")
    else:
        successes.append(f"GL implementation: {impl.group(1).strip()}")

    return successes, failures


def main():
    wait_for_devtools()
    page = open_gpu_page()
    try:
        text = dump_gpu(page)
    finally:
        close_page(page["id"])
    if not text or "Graphics Feature Status" not in text:
        print("FAIL  chrome://gpu did not render a Graphics Feature Status section")
        print("---- captured text (first 400 chars) ----")
        print(text[:400])
        return 1
    successes, failures = assert_feature_status(text)
    for s in successes:
        print(f"OK    {s}")
    for f in failures:
        print(f"FAIL  {f}")
    return 0 if not failures else 1


if __name__ == "__main__":
    sys.exit(main())

