- (void)viewDidMoveToWindow {
    [super viewDidMoveToWindow];
    // Tag the host window as Display P3 so the WindowServer composites our
    // CEF content without applying an sRGB→display profile conversion on
    // pixels that Chromium has already produced in P3 (we set
    // --force-color-profile=display-p3-d65). Without this, saturated
    // colors land on the panel inflated — orange #ED6A34 read as
    // (255,136,82) instead of (237,106,52) on Apple Silicon panels.
    self.window.colorSpace = [NSColorSpace displayP3ColorSpace];
    dispatch_async(dispatch_get_main_queue(), ^{
        [self.controller layoutBrowserView];
    });
}

