@implementation TungstenBrowserContainerView

- (NSSize)intrinsicContentSize {
    return NSMakeSize(NSViewNoIntrinsicMetric, NSViewNoIntrinsicMetric);
}

// Tag the host window as Display P3 so the WindowServer composites our CEF
// content without applying an sRGB→display profile conversion on pixels that
// Chromium has already produced in P3 (we pass --force-color-profile=display-
// p3-d65). Without this, saturated colors land on the panel inflated —
// e.g. orange #ED6A34 reads as (255,136,82) instead of (237,106,52). AppKit
// resets the window's effective color tagging across key-state and backing-
// property changes, so we reapply on each transition rather than once.
- (void)applyDisplayP3ColorSpace {
    if (self.window != nil) {
        self.window.colorSpace = [NSColorSpace displayP3ColorSpace];
    }
}

- (void)windowFocusOrBackingDidChange:(NSNotification *)note {
    [self applyDisplayP3ColorSpace];
}

- (void)viewDidMoveToWindow {
    [super viewDidMoveToWindow];

    NSNotificationCenter *center = NSNotificationCenter.defaultCenter;
    [center removeObserver:self];

    NSWindow *window = self.window;
    if (window != nil) {
        [self applyDisplayP3ColorSpace];

        NSNotificationName names[] = {
            NSWindowDidBecomeKeyNotification,
            NSWindowDidResignKeyNotification,
            NSWindowDidBecomeMainNotification,
            NSWindowDidResignMainNotification,
            NSWindowDidChangeBackingPropertiesNotification,
            NSWindowDidChangeScreenNotification,
        };
        for (size_t i = 0; i < sizeof(names) / sizeof(names[0]); ++i) {
            [center addObserver:self
                       selector:@selector(windowFocusOrBackingDidChange:)
                           name:names[i]
                         object:window];
        }
    }

    dispatch_async(dispatch_get_main_queue(), ^{
        [self.controller layoutBrowserView];
    });
}

- (void)setFrameSize:(NSSize)newSize {
    [super setFrameSize:newSize];
    [self.controller layoutBrowserView];
}

- (void)dealloc {
    [NSNotificationCenter.defaultCenter removeObserver:self];
}

@end

