// Tag both the CALayer and the host window as Display P3. Chromium produces
// P3 pixels (--force-color-profile=display-p3-d65); without explicit color
// tagging at the AppKit layer, the WindowServer applies an sRGB→display
// conversion on top, inflating saturated channels (orange #ED6A34 reads as
// (255,136,82) instead of (237,106,52)). AppKit can also desaturate
// inactive-window content, so we reapply on every key-state transition
// rather than once. Tagging the CALayer directly is more durable than
// relying solely on NSWindow.colorSpace, which is why we set both.
- (void)applyDisplayP3ColorSpace {
    NSColorSpace *p3 = [NSColorSpace displayP3ColorSpace];
    if (self.window != nil) {
        self.window.colorSpace = p3;
    }
    self.wantsLayer = YES;
    if (self.layer != nil) {
        self.layer.colorspace = p3.CGColorSpace;
    }
}

- (void)windowFocusOrBackingDidChange:(NSNotification *)note {
    NSWindow *w = self.window;
    NSString *layerCS = (self.layer.colorspace != NULL)
        ? (__bridge_transfer NSString *)CGColorSpaceCopyName(self.layer.colorspace)
        : @"<nil>";
    NSLog(@"[Tungsten color] note=%@ key=%d main=%d windowCS=%@ layerCS=%@",
          note.name, w.isKeyWindow, w.isMainWindow,
          w.colorSpace.localizedName ?: @"<nil>", layerCS);
    [self applyDisplayP3ColorSpace];
    NSString *layerCSAfter = (self.layer.colorspace != NULL)
        ? (__bridge_transfer NSString *)CGColorSpaceCopyName(self.layer.colorspace)
        : @"<nil>";
    NSLog(@"[Tungsten color]   after reapply: windowCS=%@ layerCS=%@",
          self.window.colorSpace.localizedName ?: @"<nil>", layerCSAfter);
}

